import{_ as a,o,c as m,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Commands.md","filePath":"manual-en/Commands.md","lastUpdated":1785684581000}'),s={name:"manual-en/Commands.md"};function t(r,e,c,d,i,h){return o(),m("div",null,[...e[0]||(e[0]=[n('<h3 id="_6-2-forming-commands-of-tokens" tabindex="-1">6.2 Forming commands of tokens <a class="header-anchor" href="#_6-2-forming-commands-of-tokens" aria-label="Permalink to &quot;6.2 Forming commands of tokens&quot;">​</a></h3><p>Most PSPP commands share a common structure. A command begins with a command name, such as <code>FREQUENCIES</code>, <code>DATA LIST</code>, or <code>N OF CASES</code>. The command name may be abbreviated to its first word, and each word in the command name may be abbreviated to its first three or more characters, where these abbreviations are unambiguous.</p><p>The command name may be followed by one or more <em>subcommands</em>. Each subcommand begins with a subcommand name, which may be abbreviated to its first three letters. Some subcommands accept a series of one or more specifications, which follow the subcommand name, optionally separated from it by an equals sign (‘=’). Specifications may be separated from each other by commas or spaces. Each subcommand must be separated from the next (if any) by a forward slash (‘/’).</p><p>There are multiple ways to mark the end of a command. The most common way is to end the last line of the command with a period (‘.’) as described in the previous section (see <a href="./Tokens">Tokens</a>). A blank line, or one that consists only of white space or comments, also ends a command.</p>',4)])])}const b=a(s,[["render",t]]);export{f as __pageData,b as default};
